@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class AdministrativeStaff extends Employee {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" *-- "*" Institute
Faculty "1" -- "0..1" Employee : headedBy
Institute "1" -- "*" ResearchAssistant : has
ResearchAssistant "*" -- "*" Project : involvedIn
Lecturer "*" -- "*" Course : teaches
Faculty "1" -- "*" Employee : employs

@enduml

